#include "StdAfx.h"#include "FscList.h"static char* sid = "Multiple Output (BO)";//bool SFscList::FuncParser47( VAR_PARSER ){  FuncParserdo(fsc,p,dat,tmp);  p.ValidateB();  //  SPointOut io;  io.nIn  = -1;  char FullName[256];  strcpy_s( FullName, (char*)(dat.data+1));  int L = lstrlen ( FullName );  while ( L > 0 && FullName[L-1] == ' ' )    FullName[--L] = 0;  io.nDbf = fsc->FindDbfTag( FullName, CFSC_Info::BO );  io.Out  = NULL;  p.nBuff = fsc->AddFscBuff( &io, sizeof(io) );  return true;}////void FuncDebugs47( VAR_DEBUGS )//  {//  strcat_s( str, sid );//  strcat_s( str, "\r\n------------------------------------------------------------\r\n" );//  FuncDebugsdo( p, str );//  }//void SFscList::FuncPaints47( VAR_PAINTS ){  SPointOut* dat = fsc->PointOut(p.nBuff);  if ( dat->nIn == -1 )    {    RECT rcr = p.rect; rcr.left = rcr.right-10;    CMyBrush brush( font, 0xa000e0 );    brush.Rect( rcr );    }  else    {    SDotValue* V = fsc->DotV(dat->nIn);    if ( V->dwFlags & 0x2 )      {      RECT rcr = p.rect; rcr.left = rcr.right-10;      CMyBrush brush( font, NOTCONNECTED );      brush.Rect( rcr );      }    }  int nNumb = dat->nDbf;  p.BoxR( fsc, font, nNumb, p.rect );  if ( nSelect == dat->nIn )    {    CMyPen pen( font, SELCOLOR );    pen.Rect( p.rect );    }  p.BadRect( font, dat->nIn );}//void SFscList::FuncSetLnk47( VAR_SETLNK ){  if ( x == p.rect.right )     return;  SPointOut* dat = (SPointOut*)fsc->Data(p.nBuff);  if ( dat->nIn == -1 )    dat->nIn = nLink;  SDotValue* dot = fsc->DotV(nLink);  ASS( dot->eType == enumValueDbl || dot->eType == enumValueBol );}////-----------------------------------------------------------------------------//UINT FuncCursor47( VAR_CURSOR )//  {//  SPointOut* dat = fsc->PointOut(p.nBuff);//  return dat->nIn;//  }////-----------------------------------------------------------------------------UINT* SFscList::FuncOutput47( VAR_OUTPUT ){  n = 0;  return NULL;}////-----------------------------------------------------------------------------void SFscList::FuncTimers47( VAR_TIMERS ){  SPointOut* dat = fsc->PointOut(p.nBuff);  if ( dat->nIn != -1 )    {    SDotValue* V = fsc->DotV(dat->nIn);    if ( dat->Out != NULL )      {			// Но это не очень хорошо			//const char* a = fsc->DbfName( dat->nDbf, 27 );			//int PLCADDR = atoi( a );			//Действия только при Блокировки = Да//??			if ( pExt-> IsBlk	|| PLCADDR == -1 )			//if ( PLCADDR == -1 )      {        if( V->eType == enumValueDbl )        {          double* v = (double*)dat->Out;				  *v = V->Dbl();        }        else if( V->eType == enumValueBol )        {          BYTE* v = (BYTE*)dat->Out;				  *v = V->Bol() ? 1 : 0;        }      }      if ( V->dwFlags & 0x2 )        V->dwFlags &= !0x2;      }    else      {      V->dwFlags |= 0x2;      }    }}////-----------------------------------------------------------------------------static LPCSTR s_pName[] = { "in" };int SFscList::FuncQuickWatch47( IFscStorage* fsc, LFscBase *obj, IFscStorage::SVarInfo *pvi, int cVI, LPCSTR *ppPntName ){  SPointOut* dat = (SPointOut*)fsc->Data(obj->nBuff);  SDotValue* vals[] = { fsc->DotV(dat->nIn) };  int n = 0;  for( n; n<_countof(vals) && n<cVI; ++n )  {    pvi[n].val = vals[n];    strcpy_s( pvi[n].szName, s_pName[n] );  }  if( ppPntName )    *ppPntName = fsc->DbfName( dat->nDbf, 1 );  return n;}int SFscList::SaveState47( IStateSer *psaver, IFscStorage* fsc, LFscBase *obj ){  SPointOut* dat = (SPointOut*)fsc->Data(obj->nBuff);  SDotValue* vals[] = { fsc->DotV(dat->nIn) };  for( int i=0; i<_countof(vals); ++i )  {    psaver->WriteDotV( vals[i], s_pName[i] );  }  return 0;}int SFscList::RestoreState47( IStateSer *prest, IFscStorage* fsc, LFscBase *obj ){  SPointOut* dat = (SPointOut*)fsc->Data(obj->nBuff);  SDotValue* vals[] = { fsc->DotV(dat->nIn) };  for( int i=0; i<_countof(vals); ++i )  {    prest->ReadDotV( vals[i], s_pName[i] );  }  return 0;}